const valueAt = (root: unknown, path: string): unknown =>
  path.split('.').reduce<unknown>((node, key) => {
    if (node !== null && typeof node === 'object') {
      return (node as Record<string, unknown>)[key];
    }

    return undefined;
  }, root);

describe('тексты шагов, «Перед стартом» и «Гарантии после запуска» в ru.json — дословно утвержденные', () => {
  it.each(APPROVED)('%s', (path, expected) => {
    expect(valueAt(ru, path)).toBe(expected);
  });
});

describe('измененные тексты карточек, шагов и гарантии в en.json — дословно утвержденные', () => {
  it.each(APPROVED_EN)('%s', (path, expected) => {
    expect(valueAt(en, path)).toBe(expected);
  });
});
